# Runtime v2 · MD Modifier: chuỗi, thứ tự, kích thước, dùng lại, Modifier.Node (chương mới)
# Nguồn: "Compose modifiers", "Create custom modifiers", "Migrate from Modifier.composed to Modifier.Node", "Constraints and modifier order" (developer.android.com, đọc 2026-11-23);
# Modifier.kt, ModifierNodeElement.kt, NodeChain.kt (updateFrom, actionForModifiers, Differ), Background.kt, Padding.kt @296313a4;
# Jetpack Compose by Tutorials Ch.6 (NoteColor: clip/background, padding, modifier vs Modifier); Essentials Ch.24 (border/padding, tham số modifier, then).

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.chain ----------------
    m = lambda k, vi, en=None: a('m.chain.' + k, vi, en)
    m('title', 'Sau recompose: node modifier được giữ, cập nhật hay tạo lại?', 'After recomposition: are modifier nodes kept, updated or recreated?')
    m('overview', 'Mỗi lần `Dot` chạy lại, chuỗi `Modifier` được dựng MỚI từ đầu: các element là object mới. Nhưng node phía sau (`Modifier.Node`) sống lâu trên `LayoutNode`. Compose so chuỗi mới với chuỗi cũ theo từng vị trí để quyết: dùng lại, cập nhật, hay gỡ rồi tạo node mới. Chọn một trong bốn thay đổi giữa hai lượt.', 'Every time `Dot` re-runs, the `Modifier` chain is built ANEW: its elements are new objects. But the nodes behind them (`Modifier.Node`) are long-lived on the `LayoutNode`. Compose compares the new chain with the old one position by position to decide: reuse, update, or remove and create a new node. Pick one of four changes between two passes.')
    m('wrapup', 'Luật ở commit ghim: element mới `equals` element cũ thì dùng lại node, không gọi update; cùng lớp nhưng khác dữ liệu thì gọi `update(node)` và tự invalidate phần liên quan; khác lớp ở cùng vị trí, hoặc chuỗi đổi độ dài, thì chạy diff cấu trúc: node không còn bị gỡ (detach), node mới được tạo (attach). Vì vậy `equals` của element quan trọng, và đổi CẤU TRÚC chuỗi theo điều kiện thì node ở chỗ đó mất state.', 'The rule at the pinned commit: a new element that `equals` the old one reuses the node without calling update; same class but different data calls `update(node)` and auto-invalidates what is affected; a different class at the same position, or a change in chain length, runs a structural diff: nodes no longer present are removed (detached) and new nodes are created (attached). So an element\'s `equals` matters, and conditionally changing the chain\'s STRUCTURE loses the state of the node at that spot.')
    m('simp.1', 'Tên lớp element (PaddingElement, BackgroundElement, BorderModifierNodeElement, SizeElement) theo mã ở commit ghim; `clip` thực ra là một graphicsLayer element, site chỉ ghi "clip". Mô hình không vẽ coordinator và không cho thấy mỗi element có thể gồm nhiều node.', 'Element class names (PaddingElement, BackgroundElement, BorderModifierNodeElement, SizeElement) follow the code at the pinned commit; `clip` is really a graphicsLayer element, the site just writes "clip". The model does not draw coordinators and does not show that an element may involve several nodes.')
    m('simp.2', 'Thứ tự remove/insert trong diff cấu trúc do thuật toán Myers quyết; site chỉ bảo đảm số lượng (giữ, gỡ, chèn), không bảo đảm thứ tự từng lệnh.', 'The order of removes and inserts in the structural diff is decided by the Myers algorithm; the site only guarantees the counts (kept, removed, inserted), not the order of each operation.')
    m('ctl.hint', 'Chạy "không đổi", rồi "đổi màu"; sau đó so hai cách viết modifier có điều kiện.', 'Run "nothing changed", then "colour changed"; then compare the two ways of writing a conditional modifier.')
    m('ctl.which', 'Thay đổi giữa hai lượt', 'Change between the two passes')
    for k, vi, en in [('equal', 'Không đổi (chỉ label đổi)', 'Nothing changed (only the label)'), ('update', 'Đổi màu Red → Blue', 'Colour Red → Blue'),
                      ('insert', 'Thêm border có điều kiện (else Modifier)', 'Conditional border (else Modifier)'), ('replace', 'Border hoặc shadow (khác lớp)', 'Border or shadow (different classes)')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'Chuỗi node modifier của một LayoutNode', 'The modifier node chain of one LayoutNode')
    m('diagramDesc', 'Bốn node modifier xếp từ ngoài vào trong, từ trái sang phải, kết thúc ở LayoutNode', 'Four modifier nodes from outer to inner, left to right, ending at the LayoutNode')
    for k, vi, en in [('m1', 'Vị trí 1', 'Position 1'), ('m2', 'Vị trí 2', 'Position 2'), ('m3', 'Vị trí 3', 'Position 3'), ('m4', 'Vị trí 4', 'Position 4'), ('layout', 'LayoutNode', 'LayoutNode')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('reused', 'Node dùng lại', 'Nodes reused'), ('updated', 'Node được update', 'Nodes updated'), ('inserted', 'Node tạo mới', 'Nodes created'), ('removed', 'Node bị gỡ', 'Nodes removed')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('before', 'Chuỗi lượt trước', 'Previous chain'), ('after', 'Chuỗi lượt này', 'This chain'), ('action', 'Quyết định', 'Decision')]:
        m('st.' + k, vi, en)
    S = [
        ('intro.equal', 'Lượt trước: bốn node đã có', 'The previous pass: four nodes exist', '`Dot` đã chạy một lần; `LayoutNode` của Box giữ bốn node tương ứng bốn element: padding, clip, background, size.', '`Dot` has run once; the Box\'s `LayoutNode` holds four nodes matching four elements: padding, clip, background, size.'),
        ('intro.update', 'Lượt trước: bốn node, nền Red', 'The previous pass: four nodes, a Red background', 'Giống trên; lần này lượt sau sẽ đổi `color` từ Red sang Blue.', 'As above; this time the next pass changes `color` from Red to Blue.'),
        ('intro.insert', 'Lượt trước: selected = false, ba node', 'The previous pass: selected = false, three nodes', '`then(Modifier)` với Modifier rỗng trả về chính chuỗi cũ (mã `then` ở commit ghim), nên chuỗi chỉ có padding, background, size.', '`then(Modifier)` with the empty Modifier returns the chain unchanged (the `then` code at the pinned commit), so the chain only has padding, background, size.'),
        ('intro.replace', 'Lượt trước: selected = false, có shadow', 'The previous pass: selected = false, with a shadow', 'Nhánh else là `Modifier.shadow(4.dp)`, nên chuỗi luôn có bốn element: padding, shadow, background, size.', 'The else branch is `Modifier.shadow(4.dp)`, so the chain always has four elements: padding, shadow, background, size.'),
        ('recompose.equal', 'Dot chạy lại vì label đổi', 'Dot re-runs because label changed', 'Biểu thức `Modifier.padding(8.dp)…` chạy lại và cấp phát bốn element MỚI. Element là dữ liệu nhẹ, tạo mỗi lần recompose; node mới là thứ đắt và sống lâu.', 'The `Modifier.padding(8.dp)…` expression runs again and allocates four NEW elements. Elements are lightweight data, created on every recomposition; nodes are the costly, long-lived part.'),
        ('recompose.update', 'Dot chạy lại với color = Blue', 'Dot re-runs with color = Blue', 'Bốn element mới; `BackgroundElement` giờ mang Blue.', 'Four new elements; `BackgroundElement` now carries Blue.'),
        ('recompose.insert', 'Dot chạy lại với selected = true', 'Dot re-runs with selected = true', 'Chuỗi mới có bốn element: border chen vào vị trí 2.', 'The new chain has four elements: border squeezes into position 2.'),
        ('recompose.replace', 'Dot chạy lại với selected = true', 'Dot re-runs with selected = true', 'Chuỗi mới vẫn bốn element, nhưng vị trí 2 là border thay cho shadow.', 'The new chain still has four elements, but position 2 is border instead of shadow.'),
        ('reuse', 'Vị trí {i}: equals → dùng lại', 'Position {i}: equals → reuse', '`{el}` mới bằng `{el}` cũ (`equals` so dữ liệu, không so tham chiếu), nên node được dùng lại nguyên vẹn, không gọi `update`.', 'The new `{el}` equals the old one (`equals` compares data, not references), so the node is reused as is, without calling `update`.'),
        ('update', 'Vị trí 3: cùng lớp, khác dữ liệu → update', 'Position 3: same class, different data → update', '`BackgroundElement` so `color`, `brush`, `alpha`, `shape`; Red ≠ Blue nên không bằng, nhưng cùng lớp. Compose gọi `update(node)` để node cũ nhận màu mới, rồi tự invalidate phần node đó ảnh hưởng (ở đây là vẽ).', '`BackgroundElement` compares `color`, `brush`, `alpha`, `shape`; Red ≠ Blue, so they are not equal, but the class is the same. Compose calls `update(node)` so the old node takes the new colour, then auto-invalidates what that node affects (here, drawing).'),
        ('diff', 'Độ dài khác (3 → 4): diff cấu trúc', 'Different length (3 → 4): structural diff', 'Đường nhanh chỉ dùng khi hai chuỗi dài bằng nhau. Ở đây {a} ≠ {b} nên `NodeChain` chạy diff Myers trên hai danh sách element, với "cùng một phần tử" nghĩa là equals hoặc cùng lớp.', 'The fast path only applies when both chains have the same length. Here {a} ≠ {b}, so `NodeChain` runs a Myers diff over the two element lists, where "the same item" means equal or of the same class.'),
        ('same', 'Vị trí {i}: khớp trong diff → giữ node', 'Position {i}: matched in the diff → node kept', '`{el}` khớp với element cũ: node được giữ (bằng nhau thì không update).', '`{el}` matches the old element: the node is kept (equal, so no update).'),
        ('insert', 'Vị trí {i}: tạo node mới', 'Position {i}: create a new node', '`{el}.create()` tạo node, node được gắn vào chuỗi và chạy vòng đời attach (`onAttach`), rồi phần nó ảnh hưởng được invalidate.', '`{el}.create()` builds the node, it is linked into the chain and runs its attach lifecycle (`onAttach`), then what it affects is invalidated.'),
        ('abort', 'Vị trí 2: khác lớp → bỏ đường nhanh', 'Position 2: different class → leave the fast path', 'Shadow và border khác lớp: quyết định là Replace. So tuyến tính dừng ở đây và phần còn lại của chuỗi đi qua diff cấu trúc.', 'Shadow and border are different classes: the decision is Replace. The linear comparison stops here and the rest of the chain goes through the structural diff.'),
        ('remove', 'Gỡ node shadow', 'Remove the shadow node', 'Node cũ bị invalidate rồi chạy vòng đời detach (`onDetach`). Mọi state nó giữ (ví dụ một `Animatable`) mất theo.', 'The old node is invalidated and runs its detach lifecycle (`onDetach`). Any state it held (an `Animatable`, say) goes with it.'),
        ('end.equal', 'Kết thúc: 4 node dùng lại, không việc gì thêm', 'The end: 4 nodes reused, nothing else to do', 'Recompose tạo element mới nhưng không tạo node mới nào.', 'Recomposition created new elements but no new nodes.'),
        ('end.update', 'Kết thúc: 3 dùng lại, 1 update', 'The end: 3 reused, 1 updated', 'Chỉ node nền nhận dữ liệu mới.', 'Only the background node received new data.'),
        ('end.insert', 'Kết thúc: 3 giữ, 1 tạo mới', 'The end: 3 kept, 1 created', 'Diff cấu trúc tìm ra đúng một lần chèn.', 'The structural diff found exactly one insertion.'),
        ('end.replace', 'Kết thúc: 3 giữ, 1 gỡ, 1 tạo mới', 'The end: 3 kept, 1 removed, 1 created', 'Đổi lớp element ở cùng vị trí làm node cũ mất, node mới bắt đầu từ đầu.', 'Changing the element class at the same position loses the old node; the new node starts from scratch.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('update', '`actionForModifiers` ở commit ghim: bằng nhau → dùng lại không update; cùng lớp → dùng lại và update; khác → thay. [[src:ui-nodechain-src]] [[src:ui-mne-src]]', '`actionForModifiers` at the pinned commit: equal → reuse without update; same class → reuse and update; otherwise → replace. [[src:ui-nodechain-src]] [[src:ui-mne-src]]'),
        ('diff', 'KDoc của `updateFrom`: chuỗi khác độ dài, hoặc element khác loại ở cùng vị trí, rơi vào đường chậm: diff và số chèn/xóa tối thiểu. [[src:ui-nodechain-src]]', 'The `updateFrom` KDoc: a chain of different length, or different element types at the same position, falls into the slow path: a diff with the minimum number of insertions and deletions. [[src:ui-nodechain-src]]'),
        ('remove', 'Node bị gỡ luôn được invalidate rồi chạy detach. [[src:ui-nodechain-src]]', 'A removed node is always invalidated, then detached. [[src:ui-nodechain-src]]'),
        ('end.equal', 'Tài liệu: element `ModifierNodeElement` không có state và được cấp phát mỗi lần recompose, còn `Modifier.Node` có thể có state và sống qua nhiều lần recompose. [[src:cp-custom-modifiers]]', 'The docs: `ModifierNodeElement` instances are stateless and allocated on each recomposition, while `Modifier.Node` instances can be stateful and survive many recompositions. [[src:cp-custom-modifiers]]'),
        ('end.update', 'Node tự invalidate khi được update; muốn chỉ invalidate vẽ thì override `shouldAutoInvalidate` và gọi `invalidateDraw()`. [[src:cp-custom-modifiers]]', 'Nodes auto-invalidate when updated; to invalidate only drawing, override `shouldAutoInvalidate` and call `invalidateDraw()`. [[src:cp-custom-modifiers]]'),
        ('end.insert', '`then(Modifier)` trả về chính chuỗi, nên nhánh rỗng không để lại element nào. [[src:ui-modifier-src]]', '`then(Modifier)` returns the chain itself, so the empty branch leaves no element behind. [[src:ui-modifier-src]]'),
        ('end.replace', 'Nếu node bị gỡ giữ state (animation chạy trong `coroutineScope` từ `onAttach`), state đó bắt đầu lại ở node mới. [[src:ui-nodechain-src]] [[src:cp-custom-modifiers]]', 'If the removed node held state (an animation run in its `coroutineScope` from `onAttach`), that state starts over in the new node. [[src:ui-nodechain-src]] [[src:cp-custom-modifiers]]')]:
        m('co.' + k, vi, en)
    a('cap.chain', 'Từ trái sang phải: các node modifier từ ngoài vào trong, cuối cùng là LayoutNode. Node sáng lên là node đang được so; chỉ số đếm node dùng lại, update, tạo mới và bị gỡ.', 'Left to right: modifier nodes from outer to inner, ending at the LayoutNode. The highlighted node is the one being compared; the metrics count nodes reused, updated, created and removed.')

    # ---------------- chương MD (mới) ----------------
    C = 'md'
    a(C + '.title', 'Modifier: chuỗi, thứ tự, kích thước và Modifier.Node', 'Modifiers: chains, order, sizing and Modifier.Node')
    a(C + '.essence',
      'Modifier trang trí hoặc thêm hành vi cho một composable: kích thước, padding, nền, click, cuộn, semantics. Bạn bắt đầu từ object `Modifier` rỗng và nối các hàm. Chuỗi là danh sách element có thứ tự, bất biến, và element đứng trước được áp trước, nên đổi thứ tự là đổi kết quả: `clip` trước hay sau `background`, `clickable` trước hay sau `padding`.\n'
      'Mỗi element bọc phần còn lại của chuỗi và layout bên trong (chương LO): modifier kích thước đổi constraints đi xuống, modifier vẽ vẽ trong vùng nó nhận. Mỗi lần recompose, chuỗi element được dựng lại, nhưng node phía sau (`Modifier.Node`) sống lâu và chỉ được dùng lại, cập nhật, hoặc tạo lại theo luật so sánh.\n'
      'Chương kết thúc bằng cách tự viết modifier: nối modifier có sẵn, factory `@Composable` và `Modifier.Node`.',
      'A modifier decorates or adds behaviour to a composable: size, padding, background, clicks, scrolling, semantics. You start from the empty `Modifier` object and chain functions. A chain is an ordered, immutable list of elements, and elements that come first are applied first, so changing the order changes the result: `clip` before or after `background`, `clickable` before or after `padding`.\n'
      'Each element wraps the rest of the chain and the layout inside it (chapter LO): sizing modifiers change the constraints going down, drawing modifiers draw in the area they receive. On every recomposition the element chain is rebuilt, but the nodes behind it (`Modifier.Node`) are long-lived and only reused, updated or recreated according to comparison rules.\n'
      'The chapter ends with writing your own modifiers: chaining existing ones, `@Composable` factories and `Modifier.Node`.')
    a(C + '.goal.g1', 'Đã thấy recompose dựng một chuỗi element mới', 'Saw recomposition build a new element chain')
    a(C + '.goal.g2', 'Đã chạy một thay đổi tới cuối', 'Ran one change to the end')
    a(C + '.sim.runtime.chain', 'Node modifier qua recompose', 'Modifier nodes across recomposition')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', '`Box(Modifier.size(40.dp).background(Color.Red).clip(CircleShape))`. Bạn thấy hình tròn đỏ hay hình vuông đỏ?', '`Box(Modifier.size(40.dp).background(Color.Red).clip(CircleShape))`. Do you see a red circle or a red square?')
    B(C, S, 1, 'ans', 'Hình vuông đỏ. `background` đã vẽ nền chữ nhật trước khi `clip` được áp; `clip` chỉ cắt những gì đến SAU nó trong chuỗi. Đây là ví dụ mở đầu của Jetpack Compose by Tutorials: thêm `.background(Color.Yellow)` sau `clip` sẽ thấy một hình tròn vàng trong hình vuông đỏ. Muốn tròn đỏ: `size → clip → background`. [[src:book-compose-tut]]', 'A red square. `background` has drawn a rectangular background before `clip` applies; `clip` only cuts what comes AFTER it in the chain. This is the opening example of Jetpack Compose by Tutorials: adding `.background(Color.Yellow)` after `clip` shows a yellow circle inside the red square. For a red circle: `size → clip → background`. [[src:book-compose-tut]]')

    S = 'what'
    a(C + '.sec.%s.title' % S, 'Modifier là gì, và tham số modifier', 'What a modifier is, and the modifier parameter')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Tài liệu: modifier thay đổi kích thước, layout, hành vi và hình thức; thêm thông tin như nhãn accessibility; xử lý input; thêm tương tác như clickable, scrollable, draggable. Essentials so với tham số thường: `fontSize` chỉ có nghĩa với Text, còn modifier áp được cho mọi composable. Có hơn 100 hàm modifier; danh sách đầy đủ ở trang tham chiếu. [[src:cp-modifiers]] [[src:book-compose-ess]]', 'The docs: modifiers change size, layout, behaviour and appearance; add information such as accessibility labels; process input; add interactions such as clickable, scrollable, draggable. Essentials contrasts them with ordinary parameters: `fontSize` only means something to a Text, while a modifier can be applied to any composable. There are over 100 modifier functions; the full list is on the reference page. [[src:cp-modifiers]] [[src:book-compose-ess]]')
    B(C, S, 2, 'p', 'Quy ước (KDoc của `Modifier` ở commit ghim, và Essentials): composable nhận modifier áp cho cả component thì đặt tên tham số `modifier`, mặc định `Modifier`, là tham số TÙY CHỌN ĐẦU TIÊN (sau các tham số bắt buộc, trừ lambda cuối). Modifier mặc định của component nối SAU giá trị được truyền vào. Modifier cho một phần con `foo` thì đặt tên `fooModifier`. Tài liệu thêm: truyền modifier cho composable con đầu tiên phát ra UI. [[src:ui-modifier-src]] [[src:book-compose-ess]] [[src:cp-modifiers]]', 'The convention (the `Modifier` KDoc at the pinned commit, and Essentials): a composable that takes a modifier for the whole component names the parameter `modifier`, defaults it to `Modifier`, and makes it the FIRST OPTIONAL parameter (after required parameters, except a trailing lambda). The component\'s own default modifiers are chained AFTER the passed-in value. A modifier for a subcomponent `foo` is named `fooModifier`. The docs add: pass the modifier to the first child that emits UI. [[src:ui-modifier-src]] [[src:book-compose-ess]] [[src:cp-modifiers]]')
    B(C, S, 3, 'kt', '@Composable\nfun NoteColor(\n    modifier: Modifier = Modifier,       // tham số: chữ m thường\n    color: Color,\n    size: Dp,\n    border: Dp\n) {\n    Box(\n        modifier = modifier              // ✓ nối TIẾP chuỗi người gọi truyền vào\n            .size(size)\n            .clip(CircleShape)\n            .background(color)\n            .border(BorderStroke(border, SolidColor(Color.Black)), CircleShape)\n    )\n}', '@Composable\nfun NoteColor(\n    modifier: Modifier = Modifier,       // the parameter: lowercase m\n    color: Color,\n    size: Dp,\n    border: Dp\n) {\n    Box(\n        modifier = modifier              // ✓ continue the chain the caller passed in\n            .size(size)\n            .clip(CircleShape)\n            .background(color)\n            .border(BorderStroke(border, SolidColor(Color.Black)), CircleShape)\n    )\n}')
    B(C, S, 4, 'note', 'Tutorials nhấn mạnh: `modifier` (tham số) khác `Modifier` (object rỗng) chỉ một chữ cái nhưng nghĩa khác hẳn. Viết `Modifier.size(…)` bên trong thay vì `modifier.size(…)` là âm thầm vứt mọi modifier người gọi truyền vào. Sách cũng bỏ tham số `padding` khỏi `NoteColor` khi đã có `modifier`: người gọi tự thêm `.padding(…)`. [[src:book-compose-tut]]', 'Tutorials stresses that `modifier` (the parameter) and `Modifier` (the empty object) differ by one letter but mean something entirely different. Writing `Modifier.size(…)` inside instead of `modifier.size(…)` silently throws away every modifier the caller passed. The book also removes the `padding` parameter from `NoteColor` once `modifier` exists: callers add `.padding(…)` themselves. [[src:book-compose-tut]]')
    B(C, S, 4, 'kind', 'pitfall')

    S = 'order'
    a(C + '.sec.%s.title' % S, 'Thứ tự trong chuỗi', 'Order in the chain')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'KDoc ở commit ghim: "Order is significant; modifier elements that appear first will be applied first." Mỗi hàm sửa `Modifier` do hàm trước trả về. Ví dụ của tài liệu: `clickable(onClick).padding(padding)` cho cả vùng padding nhận click; `padding(padding).clickable(onClick)` thì vùng padding không nhận click. Tài liệu so với box model của View (margin ngoài, padding trong) và nói thứ tự tường minh là lý do Compose không có modifier margin, chỉ có padding. [[src:ui-modifier-src]] [[src:cp-modifiers]]', 'The KDoc at the pinned commit: "Order is significant; modifier elements that appear first will be applied first." Each function modifies the `Modifier` returned by the previous one. The docs\' example: `clickable(onClick).padding(padding)` makes the padding area clickable too; `padding(padding).clickable(onClick)` leaves the padding area unclickable. The docs compare this with the View box model (margin outside, padding inside) and say explicit ordering is why Compose has no margin modifier, only padding. [[src:ui-modifier-src]] [[src:cp-modifiers]]')
    B(C, S, 2, 'kt', '// thứ tự modifier: viền trước hay đệm trước\nval a = Modifier.border(width = 2.dp, color = Color.Black).padding(all = 10.dp)   // viền NGOÀI padding\nval b = Modifier.padding(all = 10.dp).border(width = 2.dp, color = Color.Black)   // viền TRONG padding\n\n// Tutorials: padding trước size → khoảng trống bao quanh hình tròn 40dp\nModifier.padding(4.dp).size(40.dp).clip(CircleShape).background(Color.Red)', '// modifier order: border first or padding first\nval a = Modifier.border(width = 2.dp, color = Color.Black).padding(all = 10.dp)   // border OUTSIDE the padding\nval b = Modifier.padding(all = 10.dp).border(width = 2.dp, color = Color.Black)   // border INSIDE the padding\n\n// Tutorials: padding before size → space around the 40dp circle\nModifier.padding(4.dp).size(40.dp).clip(CircleShape).background(Color.Red)')
    B(C, S, 3, 'p', 'Cách nghĩ đúng nhất đến từ chương LO: modifier là lớp bọc quanh node layout, mỗi lớp bọc phần còn lại của chuỗi. Constraints đi xuống theo chuỗi không đổi cho tới khi gặp một modifier ảnh hưởng đo đạc; kích thước đi ngược lên. Ví dụ của trang Constraints and modifier order: `clip(CircleShape).padding(10.dp).size(100.dp)`: `clip` không đổi constraints, `padding` giảm max, `size` đặt 100; ảnh báo 100, padding làm lớp bọc thành 120. Khi vẽ, `clip` tạo mặt nạ tròn 120 dp, nhưng ảnh 100 dp nằm lùi vào trong nên kết quả không tròn như mong đợi. [[src:cp-constraints-mod]]', 'The most accurate mental model comes from chapter LO: modifiers are wrappers around the layout node, each wrapping the rest of the chain. Constraints travel down the chain unchanged until a modifier that affects measurement; sizes travel back up. The Constraints and modifier order page\'s example: `clip(CircleShape).padding(10.dp).size(100.dp)`: `clip` does not change constraints, `padding` lowers the max, `size` sets 100; the image reports 100 and padding makes the wrapper 120. When drawing, `clip` creates a 120 dp round mask, but the 100 dp image is inset, so the result is not the circle you expected. [[src:cp-constraints-mod]]')
    B(C, S, 4, 'ask', '`Modifier.size(100.dp).size(50.dp)` cho kích thước nào?', 'What size does `Modifier.size(100.dp).size(50.dp)` give?')
    B(C, S, 4, 'ans', '100 dp. `size` đầu tiên đặt constraints chính xác 100; `size` thứ hai phải tôn trọng constraints vào nên không thể thành 50. Trang Constraints and modifier order dùng đúng ví dụ này. [[src:cp-constraints-mod]]', '100 dp. The first `size` sets exact 100 constraints; the second must respect the incoming constraints, so it cannot become 50. The Constraints and modifier order page uses exactly this example. [[src:cp-constraints-mod]]')

    S = 'sizing'
    a(C + '.sec.%s.title' % S, 'Kích thước, vị trí và modifier theo scope', 'Size, position and scoped modifiers')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`size` khai báo kích thước MONG MUỐN, constraints của cha có thể ghi đè; `requiredSize` ép kích thước bất kể constraints, và khi con không theo constraints, hệ layout giấu điều đó với cha và căn giữa con (chương LO; `wrapContentSize` đổi được cách căn). `fillMaxWidth`/`fillMaxHeight`/`fillMaxSize` lấp chỗ cha cho; `widthIn`/`heightIn`/`sizeIn` đặt khoảng min/max trong constraints vào, còn bản `required…` ghi đè. `padding` theo hướng bố cục (start/end); `absolutePadding` thì không. `paddingFromBaseline` đặt khoảng tới baseline. [[src:cp-modifiers]] [[src:cp-constraints-mod]]', '`size` declares a PREFERRED size that the parent\'s constraints may override; `requiredSize` forces the size regardless, and when a child ignores its constraints, the layout system hides it from the parent and centres the child (chapter LO; `wrapContentSize` can change the alignment). `fillMaxWidth`/`fillMaxHeight`/`fillMaxSize` fill the space the parent offers; `widthIn`/`heightIn`/`sizeIn` set a min/max range within the incoming constraints, while the `required…` versions override them. `padding` follows layout direction (start/end); `absolutePadding` does not. `paddingFromBaseline` sets the distance to a baseline. [[src:cp-modifiers]] [[src:cp-constraints-mod]]')
    B(C, S, 2, 'p', '`offset(x, y)` dời vị trí so với chỗ ban đầu mà KHÔNG đổi kích thước đo, khác `padding`. Nó theo hướng bố cục (`absoluteOffset` thì không). Có hai dạng: tham số và lambda; dạng lambda đọc state ở bước đặt, đúng mẹo hoãn đọc của chương B7. [[src:cp-modifiers]] [[src:cp-phases]]', '`offset(x, y)` moves the element from its original position WITHOUT changing its measured size, unlike `padding`. It follows layout direction (`absoluteOffset` does not). It has two forms: a parameter and a lambda; the lambda form reads state in the placement step, exactly the deferred-read trick of chapter B7. [[src:cp-modifiers]] [[src:cp-phases]]')
    B(C, S, 3, 'p', 'Một số modifier chỉ có trong scope: `matchParentSize()` chỉ trong `BoxScope` (con lớn bằng Box mà không làm Box lớn ra; `fillMaxSize` thì kéo Box giãn hết chỗ), `weight()` chỉ trong `RowScope`/`ColumnScope`, `align()` trong scope tương ứng. Compose dùng scope để bạn không thể gắn modifier vô nghĩa ở chỗ khác, điều hệ View không có. Tài liệu gọi chúng là parent data modifier. Lưu ý: modifier scope chỉ có tác dụng với con TRỰC TIẾP; `weight` gắn cho Text nằm trong một Box con sẽ bị bỏ qua. [[src:cp-modifiers]] [[src:book-compose-tut]]', 'Some modifiers only exist in a scope: `matchParentSize()` only in `BoxScope` (the child is as big as the Box without growing it; `fillMaxSize` would make the Box take all available space), `weight()` only in `RowScope`/`ColumnScope`, `align()` in the matching scope. Compose uses scopes so you cannot attach a meaningless modifier elsewhere, which the View system cannot prevent. The docs call these parent data modifiers. Note: a scoped modifier only works on DIRECT children; a `weight` on a Text inside a child Box is ignored. [[src:cp-modifiers]] [[src:book-compose-tut]]')
    B(C, S, 4, 'predict', 'Trong `Row(Modifier.width(210.dp))`, `Image(Modifier.weight(2f))` và `Column(Modifier.weight(1f))`. Mỗi con rộng bao nhiêu?', 'Inside `Row(Modifier.width(210.dp))`, `Image(Modifier.weight(2f))` and `Column(Modifier.weight(1f))`. How wide is each child?')
    B(C, S, 4, 'ans', 'Image 140 dp, Column 70 dp: chia theo tỉ lệ 2 : 1 (ví dụ của tài liệu). [[src:cp-modifiers]]', 'Image 140 dp, Column 70 dp: split in a 2 : 1 ratio (the docs\' example). [[src:cp-modifiers]]')

    S = 'reuse'
    a(C + '.sec.%s.title' % S, 'Trích, nối và dùng lại modifier', 'Extracting, combining and reusing modifiers')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Modifier là object giống dữ liệu, nên lưu vào biến là "hoàn toàn ổn". `a.then(b)` nối chuỗi `b` sau chuỗi `a` (Essentials: `firstModifier.then(secondModifier)`); viết `reusable.clickable { … }` cũng là nối thêm. Thứ tự vẫn quan trọng. Ở commit ghim, `then` trả về `CombinedModifier(this, other)`, trừ khi `other` là `Modifier` rỗng thì trả về chính `this`. [[src:cp-modifiers]] [[src:book-compose-ess]] [[src:ui-modifier-src]]', 'Modifiers are data-like objects, so saving them in variables is "completely fine". `a.then(b)` appends chain `b` after chain `a` (Essentials: `firstModifier.then(secondModifier)`); writing `reusable.clickable { … }` also appends. Order still matters. At the pinned commit, `then` returns `CombinedModifier(this, other)`, unless `other` is the empty `Modifier`, in which case it returns `this`. [[src:cp-modifiers]] [[src:book-compose-ess]] [[src:ui-modifier-src]]')
    B(C, S, 2, 'p', 'Vì sao trích ra? Tài liệu nêu: modifier không phải cấp phát lại mỗi lần composable dùng nó recompose; chuỗi dài so sánh tốn công, dùng lại một instance giảm việc so; mã gọn và nhất quán. Trường hợp đáng chú ý nhất là state đổi liên tục (animation): modifier viết inline "sẽ được cấp phát mỗi lần recompose, có thể mỗi frame". Với lazy list, một `reusableItemModifier` khai báo ngoài `items { }` dùng chung cho mọi mục. Modifier có scope (như `weight`) chỉ trích được tới mức cao nhất còn hợp lệ trong scope đó. [[src:cp-modifiers]]', 'Why extract? The docs list: the modifier is not re-allocated every time a composable using it recomposes; long chains are costly to compare, and reusing one instance reduces that work; the code is cleaner and more consistent. The most notable case is frequently changing state (animation): an inline modifier "will get allocated on every recomposition and potentially for every frame". For lazy lists, a `reusableItemModifier` declared outside `items { }` is shared by every item. Scoped modifiers (such as `weight`) can only be extracted up to the highest level where the scope is still valid. [[src:cp-modifiers]]')
    B(C, S, 3, 'kt', 'val reusableModifier = Modifier.padding(12.dp).background(Color.Gray)   // một lần, ngoài composable\n\n@Composable\nfun LoadingWheelAnimation() {\n    val animatedState = animateFloatAsState(/* … */)\n    LoadingWheel(\n        modifier = reusableModifier,          // ✓ không cấp phát lại mỗi frame\n        animatedState = animatedState\n    )\n}', 'val reusableModifier = Modifier.padding(12.dp).background(Color.Gray)   // once, outside the composable\n\n@Composable\nfun LoadingWheelAnimation() {\n    val animatedState = animateFloatAsState(/* … */)\n    LoadingWheel(\n        modifier = reusableModifier,          // ✓ not re-allocated every frame\n        animatedState = animatedState\n    )\n}')

    S = 'node'
    a(C + '.sec.%s.title' % S, 'Dưới mui xe: element mỗi lượt, node sống lâu', 'Under the hood: elements per pass, long-lived nodes')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', 'KDoc ở commit ghim: `Modifier` là "an ordered, immutable collection of modifier elements". Phần lớn modifier hiện đại là một `ModifierNodeElement<N>`: một element nhẹ, chỉ giữ dữ liệu để TẠO (`create()`) và CẬP NHẬT (`update(node)`) một `Modifier.Node`. Lớp con bắt buộc cài `equals` và `hashCode` (data class là đủ). Tài liệu tóm: element không có state và được cấp phát mỗi lần recompose; node có thể có state, sống qua nhiều lần recompose và thậm chí được tái sử dụng. [[src:ui-mne-src]] [[src:cp-custom-modifiers]]', 'The KDoc at the pinned commit: a `Modifier` is "an ordered, immutable collection of modifier elements". Most modern modifiers are a `ModifierNodeElement<N>`: a lightweight element that only holds the data to CREATE (`create()`) and UPDATE (`update(node)`) a `Modifier.Node`. Subclasses must implement `equals` and `hashCode` (a data class is enough). The docs sum up: elements are stateless and allocated on every recomposition; nodes can be stateful, survive many recompositions and can even be reused. [[src:ui-mne-src]] [[src:cp-custom-modifiers]]')
    B(C, S, 2, 'p', 'Khi chuỗi mới được gán cho `LayoutNode`, `NodeChain.updateFrom` khớp nó với chuỗi node hiện có. Nếu hai chuỗi dài bằng nhau, nó so tuyến tính từng vị trí với `actionForModifiers`: element mới `==` element cũ thì dùng lại node, không update; cùng lớp thì dùng lại và gọi `update`; khác lớp thì dừng đường nhanh. Độ dài khác hoặc gặp khác lớp thì phần còn lại chạy diff Myers, với insert (tạo node, attach), remove (invalidate, detach) và same (giữ, update nếu không bằng). Mô phỏng ngay dưới đi qua bốn trường hợp này. [[src:ui-nodechain-src]]', 'When a new chain is set on a `LayoutNode`, `NodeChain.updateFrom` matches it against the existing node chain. If both chains have the same length, it compares position by position with `actionForModifiers`: a new element `==` the old one reuses the node without update; the same class reuses it and calls `update`; a different class ends the fast path. A different length or a class mismatch sends the rest through a Myers diff, with insert (create a node, attach), remove (invalidate, detach) and same (keep, update if not equal). The simulation just below walks through these four cases. [[src:ui-nodechain-src]]')
    B(C, S, 3, 'p', 'Hệ quả thực tế. (1) `equals` của element quyết định có update hay không: `BackgroundElement` so `color`, `brush`, `alpha`, `shape`, nên recompose với cùng màu không đụng gì tới node nền. (2) `Modifier.then(if (c) X else Modifier)` đổi ĐỘ DÀI chuỗi; nó vẫn đúng và diff chỉ chèn/gỡ X, nhưng X mất state mỗi lần bị gỡ. (3) `if (c) X else Y` với X, Y khác lớp ở cùng vị trí thì mỗi lần đổi là gỡ một node, tạo một node. Muốn giữ state qua thay đổi, dùng một modifier với tham số (cùng lớp → update) thay vì đổi qua lại hai modifier khác lớp. [[src:ui-nodechain-src]] [[src:ui-mne-src]]', 'Practical consequences. (1) An element\'s `equals` decides whether to update: `BackgroundElement` compares `color`, `brush`, `alpha`, `shape`, so recomposing with the same colour does not touch the background node. (2) `Modifier.then(if (c) X else Modifier)` changes the chain\'s LENGTH; it still works and the diff only inserts/removes X, but X loses its state every time it is removed. (3) `if (c) X else Y` with X and Y of different classes at the same position means every switch removes one node and creates another. To keep state across a change, use one modifier with a parameter (same class → update) instead of switching between two modifiers of different classes. [[src:ui-nodechain-src]] [[src:ui-mne-src]]')
    B(C, S, 3, 'kind', 'mechanism')

    S = 'custom'
    a(C + '.sec.%s.title' % S, 'Tự viết modifier: ba cách', 'Writing your own modifier: three ways')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Theo trang Create custom modifiers: (1) NỐI modifier có sẵn, thường là đơn giản nhất, ví dụ `fun Modifier.myBackground(color: Color) = padding(16.dp).clip(RoundedCornerShape(8.dp)).background(color)`. (2) Factory `@Composable`: một extension `@Composable` được dùng API có state như `animateFloatAsState`; luôn nối từ `this` (`this then …`), không thì các modifier trước bị mất. (3) `Modifier.Node`: API cấp thấp mà chính Compose dùng để viết modifier của nó, và là cách hiệu năng tốt nhất. [[src:cp-custom-modifiers]]', 'From the Create custom modifiers page: (1) CHAIN existing modifiers, usually the simplest, e.g. `fun Modifier.myBackground(color: Color) = padding(16.dp).clip(RoundedCornerShape(8.dp)).background(color)`. (2) A `@Composable` factory: a `@Composable` extension that can use stateful APIs such as `animateFloatAsState`; always build from `this` (`this then …`), or earlier modifiers are dropped. (3) `Modifier.Node`: the low-level API Compose itself uses to implement its modifiers, and the most performant way. [[src:cp-custom-modifiers]]')
    B(C, S, 2, 'p', 'Ba caveat của factory `@Composable`: CompositionLocal được đọc ở NƠI GỌI factory, không phải nơi modifier được dùng; nó không bao giờ được skip (hàm composable có giá trị trả về thì không skip được), nên chạy lại mỗi lần recompose; và chỉ gọi được trong composition, không trích ra ngoài được. `Modifier.composed { }` thì "không còn được khuyên dùng vì lý do hiệu năng": state trong composition, không skip được, lambda bên trong được cấp phát mới mỗi lần nên bị coi là khác. [[src:cp-custom-modifiers]] [[src:cp-modifiers-node]]', 'Three caveats of `@Composable` factories: CompositionLocals are read where the factory is CALLED, not where the modifier is used; it is never skipped (composable functions with return values cannot be skipped), so it re-runs on every recomposition; and it can only be called within composition, never hoisted out. `Modifier.composed { }` is "no longer recommended due to performance concerns": state lives in composition, it cannot be skipped, and its inner lambdas are freshly allocated each time so it is seen as changed. [[src:cp-custom-modifiers]] [[src:cp-modifiers-node]]')
    B(C, S, 3, 'kt', '// Ba phần: factory, element (không state, data class), node (có thể có state)\nfun Modifier.circle(color: Color) = this then CircleElement(color)\n\nprivate data class CircleElement(val color: Color) : ModifierNodeElement<CircleNode>() {\n    override fun create() = CircleNode(color)\n    override fun update(node: CircleNode) { node.color = color }   // sửa node cũ, KHÔNG tạo mới\n}\n\nprivate class CircleNode(var color: Color) : DrawModifierNode, Modifier.Node() {\n    override fun ContentDrawScope.draw() { drawCircle(color) }\n}', '// Three parts: factory, element (stateless, a data class), node (may be stateful)\nfun Modifier.circle(color: Color) = this then CircleElement(color)\n\nprivate data class CircleElement(val color: Color) : ModifierNodeElement<CircleNode>() {\n    override fun create() = CircleNode(color)\n    override fun update(node: CircleNode) { node.color = color }   // update the old node, do NOT create one\n}\n\nprivate class CircleNode(var color: Color) : DrawModifierNode, Modifier.Node() {\n    override fun ContentDrawScope.draw() { drawCircle(color) }\n}')
    B(C, S, 4, 'p', 'Node chọn vai trò bằng interface: `LayoutModifierNode` (đo và đặt, như chương LO), `DrawModifierNode`, `SemanticsModifierNode`, `PointerInputModifierNode`, `ParentDataModifierNode`, `LayoutAwareModifierNode`, `GlobalPositionAwareModifierNode`, `CompositionLocalConsumerModifierNode` (đọc local bằng `currentValueOf`, đúng ở nơi DÙNG), `ObserverModifierNode`, `DelegatingNode`, `TraversableNode`. Node có `coroutineScope` (thay `rememberCoroutineScope`), có `onAttach` (thay `LaunchedEffect`), và tự invalidate khi update; override `shouldAutoInvalidate = false` để tự chọn `invalidateDraw()` hay `invalidateMeasurement()`. [[src:cp-custom-modifiers]] [[src:cp-modifiers-node]]', 'A node picks its roles through interfaces: `LayoutModifierNode` (measure and place, as in chapter LO), `DrawModifierNode`, `SemanticsModifierNode`, `PointerInputModifierNode`, `ParentDataModifierNode`, `LayoutAwareModifierNode`, `GlobalPositionAwareModifierNode`, `CompositionLocalConsumerModifierNode` (reads locals with `currentValueOf`, correctly at the place of USE), `ObserverModifierNode`, `DelegatingNode`, `TraversableNode`. A node has a `coroutineScope` (instead of `rememberCoroutineScope`), an `onAttach` (instead of `LaunchedEffect`), and auto-invalidates when updated; override `shouldAutoInvalidate = false` to choose between `invalidateDraw()` and `invalidateMeasurement()` yourself. [[src:cp-custom-modifiers]] [[src:cp-modifiers-node]]')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Truyền `Modifier.padding(16.dp)` vào `NoteColor(modifier = …)` nhưng không thấy padding đâu.', 'Passing `Modifier.padding(16.dp)` to `NoteColor(modifier = …)` shows no padding at all.')
    B(C, S, 1, 'cause', 'Bên trong viết `Box(modifier = Modifier.size(size)…)`: chữ M HOA bắt đầu một chuỗi mới và bỏ tham số `modifier`.', 'Inside, the code says `Box(modifier = Modifier.size(size)…)`: the UPPERCASE M starts a new chain and drops the `modifier` parameter.')
    B(C, S, 1, 'fix', 'Bắt đầu chuỗi bên trong từ `modifier` (chữ thường): `modifier.size(size)…`. [[src:book-compose-tut]]', 'Start the inner chain from `modifier` (lowercase): `modifier.size(size)…`. [[src:book-compose-tut]]')
    B(C, S, 2, 'bug', 'Hàng trong danh sách có vùng chạm nhỏ hơn hình: chạm vào phần lề trống không có phản hồi.', 'A list row has a smaller touch area than it looks: tapping the empty margin does nothing.')
    B(C, S, 2, 'cause', '`Modifier.padding(16.dp).clickable { … }`: `clickable` đứng sau `padding` nên chỉ nhận vùng bên trong padding.', '`Modifier.padding(16.dp).clickable { … }`: `clickable` comes after `padding`, so it only covers the area inside the padding.')
    B(C, S, 2, 'fix', 'Đặt `clickable` trước `padding` khi muốn cả vùng nhận click. [[src:cp-modifiers]]', 'Put `clickable` before `padding` when the whole area should be clickable. [[src:cp-modifiers]]')
    B(C, S, 3, 'bug', 'Một modifier "nhấp nháy" tự viết (Modifier.Node chạy `Animatable` trong `onAttach`) bị chạy lại từ đầu mỗi khi một hàng được chọn hoặc bỏ chọn.', 'A hand-written "blink" modifier (a Modifier.Node running an `Animatable` from `onAttach`) restarts from the beginning every time a row is selected or deselected.')
    B(C, S, 3, 'cause', 'Mã viết `if (selected) Modifier.blink(Red) else Modifier.blink2(Gray)`: hai element KHÁC LỚP ở cùng vị trí. Mỗi lần đổi, `actionForModifiers` trả về Replace: node cũ bị gỡ (detach), node mới được tạo (attach), animation bắt đầu lại.', 'The code says `if (selected) Modifier.blink(Red) else Modifier.blink2(Gray)`: two elements of DIFFERENT CLASSES at the same position. On every switch `actionForModifiers` returns Replace: the old node is removed (detached), a new node is created (attached), and the animation starts over.')
    B(C, S, 3, 'fix', 'Một modifier, một lớp element, màu là tham số: `Modifier.blink(if (selected) Red else Gray)`. Cùng lớp, khác dữ liệu → `update(node)` sửa màu trên node cũ, animation tiếp tục. [[src:ui-nodechain-src]]', 'One modifier, one element class, the colour as a parameter: `Modifier.blink(if (selected) Red else Gray)`. Same class, different data → `update(node)` changes the colour on the old node and the animation continues. [[src:ui-nodechain-src]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Sắp lại để được: hình tròn đỏ 40 dp, viền đen 2 dp theo hình tròn, khoảng trống 4 dp bao quanh. Các mảnh: `.background(Color.Red)`, `.padding(4.dp)`, `.border(2.dp, Color.Black, CircleShape)`, `.size(40.dp)`, `.clip(CircleShape)`.', 'Reorder to get: a 40 dp red circle, a 2 dp black circular border, 4 dp of space around it. The pieces: `.background(Color.Red)`, `.padding(4.dp)`, `.border(2.dp, Color.Black, CircleShape)`, `.size(40.dp)`, `.clip(CircleShape)`.')
    B(C, S, 1, 'hint', 'Khoảng trống phải nằm NGOÀI hình; clip phải đứng trước nền.', 'The space must be OUTSIDE the shape; clip must come before the background.')
    B(C, S, 1, 'solkt', 'Modifier\n    .padding(4.dp)\n    .size(40.dp)\n    .clip(CircleShape)\n    .background(Color.Red)\n    .border(2.dp, Color.Black, CircleShape)')
    B(C, S, 1, 'sol', 'Đúng thứ tự của `NoteColor` trong Tutorials (trước khi sách chuyển padding ra cho người gọi).', 'Exactly the order of `NoteColor` in Tutorials (before the book moves the padding out to the caller).')
    B(C, S, 2, 'ex', 'Trong sim, với chuỗi `padding · clip · background(color) · size`, recompose mà chỉ đổi `size(40.dp)` thành `size(48.dp)` thì có mấy node dùng lại, mấy node update, mấy node tạo mới?', 'In the sim, with the chain `padding · clip · background(color) · size`, a recomposition that only changes `size(40.dp)` to `size(48.dp)` reuses, updates and creates how many nodes?')
    B(C, S, 2, 'hint', 'Độ dài có đổi không? Lớp của element ở vị trí 4 có đổi không?', 'Does the length change? Does the class of the element at position 4 change?')
    B(C, S, 2, 'sol', '3 dùng lại, 1 update, 0 tạo mới. Cùng độ dài nên đi đường nhanh; vị trí 4 cùng lớp `SizeElement` nhưng khác dữ liệu nên `update`. Node size là layout modifier nên update làm đo lại.', '3 reused, 1 updated, 0 created. Same length, so the fast path; position 4 is the same `SizeElement` class with different data, so `update`. The size node is a layout modifier, so the update triggers remeasurement.')
    B(C, S, 3, 'ex', 'Viết `Modifier.fixedPadding()` (16 dp mọi phía) bằng `Modifier.Node` và `LayoutModifierNode`, nối với chương LO.', 'Write `Modifier.fixedPadding()` (16 dp on every side) with `Modifier.Node` and `LayoutModifierNode`, tying back to chapter LO.')
    B(C, S, 3, 'hint', 'Không có tham số nên element có thể là `data object` và `update` rỗng. Trong `measure`: giảm constraints bằng `offset`, đo con, cộng padding vào kích thước, đặt con ở (padding, padding).', 'There are no parameters, so the element can be a `data object` with an empty `update`. In `measure`: shrink the constraints with `offset`, measure the child, add the padding to the size, place the child at (padding, padding).')
    B(C, S, 3, 'solkt', 'fun Modifier.fixedPadding() = this then FixedPaddingElement\n\ndata object FixedPaddingElement : ModifierNodeElement<FixedPaddingNode>() {\n    override fun create() = FixedPaddingNode()\n    override fun update(node: FixedPaddingNode) {}\n}\n\nclass FixedPaddingNode : LayoutModifierNode, Modifier.Node() {\n    private val PADDING = 16.dp\n    override fun MeasureScope.measure(measurable: Measurable, constraints: Constraints): MeasureResult {\n        val paddingPx = PADDING.roundToPx()\n        val horizontal = paddingPx * 2\n        val vertical = paddingPx * 2\n        val placeable = measurable.measure(constraints.offset(-horizontal, -vertical))\n        val width = constraints.constrainWidth(placeable.width + horizontal)\n        val height = constraints.constrainHeight(placeable.height + vertical)\n        return layout(width, height) { placeable.place(paddingPx, paddingPx) }\n    }\n}')
    B(C, S, 3, 'sol', 'Đây là ví dụ "zero parameters" của trang Create custom modifiers. Con vẫn chỉ được đo một lần.', 'This is the "zero parameters" example of the Create custom modifiers page. The child is still measured only once.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Vì sao Compose không có modifier margin?', 'Why does Compose have no margin modifier?')
    B(C, S, 1, 'ans', 'Vì thứ tự trong chuỗi đã tường minh: padding đặt trước hay sau một modifier khác đóng vai trò margin hay padding.', 'Because the order in the chain is explicit: padding placed before or after another modifier acts as margin or padding.')
    B(C, S, 2, 'ask', 'Element và node khác nhau ở đâu?', 'How do elements and nodes differ?')
    B(C, S, 2, 'ans', 'Element nhẹ, không state, tạo mới mỗi lần recompose; node có thể có state, sống lâu trên LayoutNode và được dùng lại hoặc update.', 'Elements are lightweight, stateless and new on every recomposition; nodes can hold state, live long on the LayoutNode and are reused or updated.')
    B(C, S, 3, 'ask', 'Ba quyết định khi khớp element mới với node cũ?', 'The three decisions when matching a new element with an old node?')
    B(C, S, 3, 'ans', 'Bằng nhau → dùng lại; cùng lớp → update; khác lớp (hoặc độ dài khác) → diff cấu trúc với chèn/gỡ.', 'Equal → reuse; same class → update; different class (or a different length) → structural diff with insert/remove.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Chuỗi `size(40.dp)`, `background(Red)`, `clip(CircleShape)` theo đúng thứ tự đó cho hình gì?', 'What shape do `size(40.dp)`, `background(Red)`, `clip(CircleShape)`, in that order, give?',
         'Hình vuông đỏ.', 'A red square.', 'Nền đã vẽ trước khi clip áp dụng.', 'The background is drawn before clip applies.'),
        ('q2', 'Tham số modifier nên đứng ở đâu trong danh sách tham số?', 'Where should the modifier parameter go in the parameter list?',
         'Tham số tùy chọn đầu tiên.', 'The first optional parameter.', 'Theo KDoc của Modifier và Essentials.', 'Per the Modifier KDoc and Essentials.'),
        ('q3', '`weight()` dùng được ở đâu?', 'Where can `weight()` be used?',
         'Con trực tiếp trong RowScope/ColumnScope.', 'Direct children in RowScope/ColumnScope.', 'Là parent data modifier có scope.', 'It is a scoped parent data modifier.'),
        ('q4', 'Vì sao `Modifier.composed {}` không còn được khuyên dùng?', 'Why is `Modifier.composed {}` no longer recommended?',
         'Vì hiệu năng.', 'Performance.', 'Không skip được, state nằm trong composition, lambda mới mỗi lần làm nó luôn bị coi là khác; dùng Modifier.Node.', 'Not skippable, state lives in composition, fresh lambdas make it always look changed; use Modifier.Node.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
